#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int num_threads = 1;

    // Compute per-thread local reverse prefix sums and each thread's total block sum.
    std::vector<long long> blockSums;
    std::vector<long long> offsets;

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();

        #pragma omp single
        {
            num_threads = omp_get_num_threads();
            blockSums.assign(static_cast<std::size_t>(num_threads), 0LL);
            offsets.assign(static_cast<std::size_t>(num_threads), 0LL);
        }

        const std::size_t t = static_cast<std::size_t>(num_threads);
        const std::size_t chunk = (n + t - 1) / t;
        const std::size_t start = static_cast<std::size_t>(tid) * chunk;
        std::size_t end = start + chunk;
        if (end > n) end = n;

        long long local = 0;

        // Reverse prefix within this block: from low to high index accumulating x[j-1].
        if (start < end) {
            for (std::size_t j = start; j < end; ++j) {
                local += static_cast<long long>(x[j] );
                output[j] = static_cast<int>(local); // temporary local-only prefix
            }
        }

        blockSums[static_cast<std::size_t>(tid)] = local;

        #pragma omp barrier

        // Compute offset for this thread = sum of all previous block sums.
        #pragma omp single
        {
            long long running = 0;
            for (int k = 0; k < num_threads; ++k) {
                offsets[static_cast<std::size_t>(k)] = running;
                running += blockSums[static_cast<std::size_t>(k)];
            }
        }

        #pragma omp barrier

        const long long off = offsets[static_cast<std::size_t>(tid)];
        if (start < end && off != 0) {
            for (std::size_t j = start; j < end; ++j) {
                output[j] = static_cast<int>(static_cast<long long>(output[j]) + off);
            }
        }
    }
}
